import{_ as s,o as i,c as e,a5 as l}from"./chunks/framework.C1a7WKBV.js";const c=JSON.parse('{"title":"Claude Code 进阶玩法","description":"Plan 模式、自定义命令、Hooks、MCP 与子代理——把 Claude Code 用出十倍效率。","frontmatter":{"title":"Claude Code 进阶玩法","description":"Plan 模式、自定义命令、Hooks、MCP 与子代理——把 Claude Code 用出十倍效率。"},"headers":[],"relativePath":"tips/claude-code-advanced.md","filePath":"tips/claude-code-advanced.md","lastUpdated":1788838685000}'),t={name:"tips/claude-code-advanced.md"};function n(h,a,p,d,o,r){return i(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="claude-code-进阶玩法" tabindex="-1">Claude Code 进阶玩法 <a class="header-anchor" href="#claude-code-进阶玩法" aria-label="Permalink to &quot;Claude Code 进阶玩法&quot;">​</a></h1><p>装好并接入 STJAPI 之后，Claude Code 还藏着一整套进阶能力。用好这几招，它就不只是&quot;对话式补全&quot;，而是能规划、自动化、并行干活的工程队友。</p><p>本篇是《<a href="/ai-handbook/tips/roadmap">从零到驾驭 AI：成长路径</a>》第五阶段的展开。还没安装的先看 <a href="/ai-handbook/clients/claude-code">Claude Code 全平台安装</a>。</p><h2 id="_1-plan-模式-先想清楚再动手" tabindex="-1">1. Plan 模式：先想清楚再动手 <a class="header-anchor" href="#_1-plan-模式-先想清楚再动手" aria-label="Permalink to &quot;1. Plan 模式：先想清楚再动手&quot;">​</a></h2><h3 id="_1-1-什么时候用" tabindex="-1">1.1 什么时候用 <a class="header-anchor" href="#_1-1-什么时候用" aria-label="Permalink to &quot;1.1 什么时候用&quot;">​</a></h3><p>改动跨多个文件、方案有多种选择、或者你还没想清楚怎么做时，先进 Plan 模式。按 <code>Shift+Tab</code> 两次切换到 plan mode。</p><h3 id="_1-2-它做什么" tabindex="-1">1.2 它做什么 <a class="header-anchor" href="#_1-2-它做什么" aria-label="Permalink to &quot;1.2 它做什么&quot;">​</a></h3><p>Plan 模式下 Claude 只读代码、搜索文件、设计方案，不修改任何文件。它会产出一份实现计划等你审批，批准后才进入执行。</p><h3 id="_1-3-实用建议" tabindex="-1">1.3 实用建议 <a class="header-anchor" href="#_1-3-实用建议" aria-label="Permalink to &quot;1.3 实用建议&quot;">​</a></h3><ul><li>复杂需求先 Plan 再执行，能挡掉大部分方向性返工。</li><li>计划里的每一步都可以批注修改，别客气，直接提。</li><li>日常小改动不必走 Plan，避免仪式感拖慢节奏。</li></ul><h2 id="_2-自定义斜杠命令" tabindex="-1">2. 自定义斜杠命令 <a class="header-anchor" href="#_2-自定义斜杠命令" aria-label="Permalink to &quot;2. 自定义斜杠命令&quot;">​</a></h2><h3 id="_2-1-创建方法" tabindex="-1">2.1 创建方法 <a class="header-anchor" href="#_2-1-创建方法" aria-label="Permalink to &quot;2.1 创建方法&quot;">​</a></h3><p>把常用提示词存成文件，就变成可复用的斜杠命令：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.claude/commands/        项目级，随仓库共享</span></span>
<span class="line"><span>~/.claude/commands/      用户级，所有项目可用</span></span></code></pre></div><p>例如创建 <code>.claude/commands/review.md</code>：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">审查当前未提交的改动：</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 逐文件检查逻辑错误、边界情况和安全问题</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 检查是否符合 CLAUDE.md 中的规范</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 按严重程度列出问题清单</span></span></code></pre></div><p>之后在会话里输入 <code>/review</code> 即可调用。</p><h3 id="_2-2-参数与动态内容" tabindex="-1">2.2 参数与动态内容 <a class="header-anchor" href="#_2-2-参数与动态内容" aria-label="Permalink to &quot;2.2 参数与动态内容&quot;">​</a></h3><p>文件里可以用 <code>$ARGUMENTS</code> 接收参数（<code>/review focus on security</code>），用 <code>!</code> 前缀注入命令输出（如 <code>!\`git diff\`</code> 自动带上当前改动）。</p><h2 id="_3-hooks-把规矩变成自动执行" tabindex="-1">3. Hooks：把规矩变成自动执行 <a class="header-anchor" href="#_3-hooks-把规矩变成自动执行" aria-label="Permalink to &quot;3. Hooks：把规矩变成自动执行&quot;">​</a></h2><h3 id="_3-1-hooks-是什么" tabindex="-1">3.1 Hooks 是什么 <a class="header-anchor" href="#_3-1-hooks-是什么" aria-label="Permalink to &quot;3.1 Hooks 是什么&quot;">​</a></h3><p>Hooks 是在特定事件（如每次编辑文件后、提交前）自动执行的 shell 命令，配置在 <code>.claude/settings.json</code>。它不靠 AI 自觉，是强制执行的。</p><h3 id="_3-2-典型用法" tabindex="-1">3.2 典型用法 <a class="header-anchor" href="#_3-2-典型用法" aria-label="Permalink to &quot;3.2 典型用法&quot;">​</a></h3><ul><li>编辑代码后自动运行格式化。</li><li>每次改动后自动跑 typecheck，失败立即反馈给 AI。</li><li>阻止 AI 修改某些敏感文件。</li></ul><h3 id="_3-3-示例" tabindex="-1">3.3 示例 <a class="header-anchor" href="#_3-3-示例" aria-label="Permalink to &quot;3.3 示例&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;hooks&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;PostToolUse&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;matcher&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Edit|Write&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;hooks&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npx prettier --write </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">$CLAUDE_FILE_PATHS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>配置后 Claude 每次写完文件，prettier 自动格式化，AI 和你都省心。</p><h2 id="_4-mcp-给-claude-接上外部工具" tabindex="-1">4. MCP：给 Claude 接上外部工具 <a class="header-anchor" href="#_4-mcp-给-claude-接上外部工具" aria-label="Permalink to &quot;4. MCP：给 Claude 接上外部工具&quot;">​</a></h2><h3 id="_4-1-mcp-是什么" tabindex="-1">4.1 MCP 是什么 <a class="header-anchor" href="#_4-1-mcp-是什么" aria-label="Permalink to &quot;4.1 MCP 是什么&quot;">​</a></h3><p>Model Context Protocol 是连接外部工具的标准协议。装上 MCP 服务器，Claude 就能查数据库、调浏览器、读文档、操作第三方服务。</p><h3 id="_4-2-添加方法" tabindex="-1">4.2 添加方法 <a class="header-anchor" href="#_4-2-添加方法" aria-label="Permalink to &quot;4.2 添加方法&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">启动命</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">令</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>例如接入 Playwright 浏览器自动化：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @playwright/mcp@latest</span></span></code></pre></div><p>会话里用 <code>/mcp</code> 查看已接入的服务器状态。</p><h3 id="_4-3-值得先试的几个" tabindex="-1">4.3 值得先试的几个 <a class="header-anchor" href="#_4-3-值得先试的几个" aria-label="Permalink to &quot;4.3 值得先试的几个&quot;">​</a></h3><ul><li><strong>Playwright / Puppeteer</strong>：让 Claude 打开真实浏览器验证页面效果。</li><li><strong>数据库 MCP</strong>：直接查表结构和数据，写 SQL 不靠猜。</li><li><strong>GitHub MCP</strong>：读写 issue 和 PR，省去来回切换。</li></ul><p>按需接入，装太多反而占用上下文。</p><h2 id="_5-子代理-并行干活" tabindex="-1">5. 子代理：并行干活 <a class="header-anchor" href="#_5-子代理-并行干活" aria-label="Permalink to &quot;5. 子代理：并行干活&quot;">​</a></h2><h3 id="_5-1-适用场景" tabindex="-1">5.1 适用场景 <a class="header-anchor" href="#_5-1-适用场景" aria-label="Permalink to &quot;5.1 适用场景&quot;">​</a></h3><p>大范围代码搜索、批量重构、多个独立子任务。主会话派活给子代理，各自独立上下文，干完汇总回来，主会话的上下文不被塞爆。</p><h3 id="_5-2-用法" tabindex="-1">5.2 用法 <a class="header-anchor" href="#_5-2-用法" aria-label="Permalink to &quot;5.2 用法&quot;">​</a></h3><p>直接用自然语言派活即可：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>并行做三件事：</span></span>
<span class="line"><span>1. 找出所有直接操作 DOM 的组件</span></span>
<span class="line"><span>2. 检查所有 API 调用是否都有错误处理</span></span>
<span class="line"><span>3. 统计还没写测试的模块</span></span></code></pre></div><p>Claude 会自动拆给子代理并行执行。你也可以在 <code>.claude/agents/</code> 里定义带专属提示词的子代理类型。</p><h3 id="_5-3-进阶技巧" tabindex="-1">5.3 进阶技巧 <a class="header-anchor" href="#_5-3-进阶技巧" aria-label="Permalink to &quot;5.3 进阶技巧&quot;">​</a></h3><ul><li>探索类、审查类任务优先派子代理，主会话专注核心实现。</li><li>子代理是全新上下文，派活时把背景、文件路径、期望产出说清楚。</li></ul><h2 id="_6-日常组合拳" tabindex="-1">6. 日常组合拳 <a class="header-anchor" href="#_6-日常组合拳" aria-label="Permalink to &quot;6. 日常组合拳&quot;">​</a></h2><p>一套经过验证的工作流：</p><ol><li>进 Plan 模式出方案，确认后执行。</li><li>执行中让子代理并行做搜索与审查。</li><li>Hooks 自动格式化与跑检查，问题即时暴露。</li><li>高频操作沉淀为自定义命令，团队共享。</li><li>需要外部能力时接入对应 MCP。</li></ol><p>相关阅读：《<a href="/ai-handbook/tips/ai-coding-principles">通用 AI 编程方法论</a>》（自动化之前先把协作习惯养对）、《<a href="/ai-handbook/tips/token-efficiency">效率与省钱技巧</a>》。</p>`,51)])])}const u=s(t,[["render",n]]);export{c as __pageData,u as default};
